--

LOCK TABLES `clipper_site_htmlsnippets` WRITE;
/*!40000 ALTER TABLE `clipper_site_htmlsnippets` DISABLE KEYS */;
INSERT INTO `clipper_site_htmlsnippets` VALUES (1,'mm_rules','(sample) Default ManagerManager rules plus Sideshow, Sidebar tab rules',0,3,0,'// Uncomment this line (remove the leading \'// \') to hide longtitle if you do not use it.\r\n// mm_hideFields(\'longtitle\');\r\n\r\n// Uncomment this if you use [*description*] in a description meta tag\r\n// mm_changeFieldHelp(\'description\', \'Description for search engines. Optional. Leave blank if unsure\'); \r\n\r\n// Uncomment the following to hide some often unused fields from all users\r\n// mm_hideFields(\'log\');\r\n// mm_hideFields(\'parent\');\r\n// mm_hideFields(\'link_attributes\');\r\n// mm_hideFields(\'which_editor\');\r\n// mm_hideFields(\'is_richtext\');\r\n\r\n// Examples of changing the help text. Uncomment to use these or write your own.\r\n// mm_changeFieldHelp(\'pagetitle\', \'Title of this page\');\r\n// mm_changeFieldHelp(\'menutitle\', \'An optional title for this page to be used in menus. Usually shorter if used.\');\r\n\r\n// Uncomment the following to hide the fields from all but admins\r\n// mm_hideFields(\'cacheable\', \'!1\');\r\n// mm_hideFields(\'clear_cache\', \'!1\');\r\n// mm_hideFields(\'is_folder\', \'!1\');\r\n// mm_hideFields(\'content_dispo\', \'!1\');\r\n// mm_hideFields(\'content_type\', \'!1\');\r\n\r\n\r\n// -----[Template Home [Slideshow]] ---- // \r\nmm_createTab(\'Slideshow\', \'slideshow\', \'\', \'4\', \'<p><strong>Instructions:</strong> Insert image and caption for each slide in the Home Page.</p><div class=\\\"split\\\"></div><br />\');\r\nmm_moveFieldsToTab(\'tvshow-slideshow,tvslide-img1,tvslide-text1,tvslide-img2,tvslide-text2,tvslide-img3,tvslide-text3,tvslide-img4,tvslide-text4\', \'slideshow\');\r\n\r\n// -----[Template Home [Sidebar]] ---- // \r\nmm_createTab(\'Sidebar\', \'sidebar\', \'\', \'4\', \'<p><strong>Instructions:</strong> Insert title and content for each box of the sidebar.</p><div class=\\\"split\\\"></div><br />\');\r\nmm_moveFieldsToTab(\'tvsidebar-title1,tvsidebar-text1,tvsidebar-title2,tvsidebar-text2,tvsidebar-title3,tvsidebar-text3,tvsidebar-title4,tvsidebar-text4\', \'sidebar\');\r\n',0),(2,'WebLoginSideBar','WebLogin Tpl',0,2,0,'<!-- #declare:separator <hr> -->\r\n<!-- login form section-->\r\n<form method=\"post\" name=\"loginfrm\" action=\"[+action+]\">\r\n    <input type=\"hidden\" value=\"[+rememberme+]\" name=\"rememberme\" />\r\n    <fieldset>\r\n        <h3>Your Login Details</h3>\r\n        <label for=\"username\">User: <input type=\"text\" name=\"username\" id=\"username\" tabindex=\"1\" onkeypress=\"return webLoginEnter(document.loginfrm.password);\" value=\"[+username+]\" /></label>\r\n    	<label for=\"password\">Password: <input type=\"password\" name=\"password\" id=\"password\" tabindex=\"2\" onkeypress=\"return webLoginEnter(document.loginfrm.cmdweblogin);\" value=\"\" /></label>\r\n    	<input type=\"checkbox\" id=\"checkbox_1\" name=\"checkbox_1\" tabindex=\"3\" size=\"1\" value=\"\" [+checkbox+] onclick=\"webLoginCheckRemember()\" /><label for=\"checkbox_1\" class=\"checkbox\">Remember me</label>\r\n    	<input type=\"submit\" value=\"[+logintext+]\" name=\"cmdweblogin\" class=\"button\" />\r\n	<a href=\"#\" onclick=\"webLoginShowForm(2);return false;\" id=\"forgotpsswd\">Forget Your Password?</a>\r\n	</fieldset>\r\n</form>\r\n<hr>\r\n<!-- log out hyperlink section -->\r\n<h4>You\'re already logged in</h4>\r\nDo you wish to <a href=\"[+action+]\" class=\"button\">[+logouttext+]</a>?\r\n<hr>\r\n<!-- Password reminder form section -->\r\n<form name=\"loginreminder\" method=\"post\" action=\"[+action+]\">\r\n    <fieldset>\r\n        <h3>It happens to everyone...</h3>\r\n        <input type=\"hidden\" name=\"txtpwdrem\" value=\"0\" />\r\n        <label for=\"txtwebemail\">Enter the email address of your account to reset your password: <input type=\"text\" name=\"txtwebemail\" id=\"txtwebemail\" size=\"24\" /></label>\r\n        <label>To return to the login form, press the cancel button.</label>\r\n    	<input type=\"submit\" value=\"Submit\" name=\"cmdweblogin\" class=\"button\" /> <input type=\"reset\" value=\"Cancel\" name=\"cmdcancel\" onclick=\"webLoginShowForm(1);\" class=\"button\" style=\"clear:none;display:inline\" />\r\n    </fieldset>\r\n</form>\r\n\r\n',0),(3,'head','Head template [Title, meta, CSS, JS]',0,0,0,'<!DOCTYPE html>\r\n<!--[if lt IE 7]>      <html class=\"no-js lt-ie9 lt-ie8 lt-ie7\"> <![endif]-->\r\n<!--[if IE 7]>         <html class=\"no-js lt-ie9 lt-ie8\"> <![endif]-->\r\n<!--[if IE 8]>         <html class=\"no-js lt-ie9\"> <![endif]-->\r\n<!--[if gt IE 8]><!--> <html class=\"no-js\"> <!--<![endif]-->\r\n<head>\r\n\r\n	<!-- [Meta] -->		\r\n	<meta http-equiv=\"Content-Type\" content=\"text/html; charset=[(modx_charset)]\" />\r\n	<meta name=\"description\" content=\"[*description*]\">\r\n	<meta name=\"viewport\" content=\"width=device-width\">	\r\n	<!-- [/End Meta] -->	\r\n	\r\n	<title>[*pagetitle*] | [(site_name)]</title>\r\n	<base href=\"[(site_url)]\" />\r\n\r\n	<!-- [CSS] -->	\r\n	<link rel=\"stylesheet\" type=\"text/css\" href=\"assets/templates/clipperdemo/css/foundation.css\"/>\r\n	<link rel=\"stylesheet\" type=\"text/css\" href=\"assets/templates/clipperdemo/css/layout.css\"/>\r\n	<link rel=\"stylesheet\" type=\"text/css\" href=\"http://fonts.googleapis.com/css?family=Merriweather+Sans\"/>\r\n	<link rel=\"shortcut icon\" href=\"assets/templates/clipperdemo/favicon.png\" />\r\n	<!-- [/End CSS] -->	\r\n	\r\n	<!-- [JavaScripts] -->    \r\n        <script src=\"[(jquery_url)]\"></script>\r\n        <script src=\"assets/templates/clipperdemo/js/javascript.js\"></script>\r\n        <script src=\"assets/templates/clipperdemo/js/settings.js\"></script>\r\n\r\n	<!--[if lt IE 9]><script src=\"http://css3-mediaqueries-js.googlecode.com/svn/trunk/css3-mediaqueries.js\"></script><![endif]-->	 \r\n	<!-- [/End JavaScripts] -->    \r\n	\r\n</head>',0),(4,'header','Header template [Logo, Search, Menu]',0,8,0,'<!-- [Header] -->\r\n<header id=\"header\">\r\n\r\n	<!-- [Logo and Search] -->\r\n	<div class=\"row\">\r\n		<div class=\"small-9 large-8 columns\">\r\n			<div id=\"header-logo\">\r\n				<a href=\"[~1~]\">[(site_name)]</a>\r\n			</div>\r\n		</div>\r\n		<div class=\"small-3 large-4 columns\" id=\"header-mobile\">\r\n			<span id=\"header-menu-mobile\">Show/Hide Menu</span>\r\n			<span id=\"header-search-mobile\">Search</span>\r\n		</div>			\r\n		<div class=\"small-3 large-4 columns\" id=\"header-search\">\r\n			<div id=\"header-search-form\">\r\n				[!AjaxSearch? \r\n           				&ajaxSearch=`0` \r\n           				&showResults=`0` \r\n           				&landingPage=`7` \r\n           				&showIntro=`0` \r\n           				&tplInput=`ajaxsearch` \r\n           				&language=`english` \r\n                		!]\r\n			</div>	\r\n		</div>	\r\n	</div>	\r\n	<!-- [/End Logo and Search] -->	\r\n	\r\n	<!-- [Header Menu] -->\r\n	<div class=\"row\" id=\"header-menu\">\r\n		<div class=\"small-12 columns\">\r\n			<nav>\r\n				[[Wayfinder? \r\n					&startId=`0` \r\n					&level=`2` 			\r\n					&sortBy=`menuindex`\r\n					&sortOrder=`ASC`\r\n				]]\r\n			</nav>\r\n		</div>\r\n	</div>	\r\n	<!-- [/End Header Menu] -->\r\n	\r\n</header>\r\n<!-- [/End Header] -->',0),(5,'footer','Footer template',0,8,0,'<!-- [Footer] -->\r\n<footer id=\"footer\">\r\n	<div class=\"row\">\r\n		<div class=\"large-12 columns\">\r\n			 &copy; Powered by <a href=\"http://www.clippercms.com\" target=\"_blank\">ClipperCMS</a>\r\n		</div>	\r\n	</div>\r\n</footer>\r\n<!-- [/End Footer] -->',0),(6,'ajaxsearch','AjaxSearch template',0,8,0,'[+as.showInputForm:is=`1`:then=`\r\n		<!-- [Search Form] -->\r\n		<form id=\"[+as.formId+]\" action=\"[+as.formAction+]\" method=\"post\">\r\n\r\n			<input type=\"hidden\" name=\"advSearch\" value=\"[+as.advSearch+]\" />\r\n			<input type=\"text\" name=\"search\" value=\"\" placeholder=\"Search...\" [+as.inputOptions+] />\r\n			<input type=\"submit\" name=\"sub\" value=\"\" />\r\n			 \r\n		</form>\r\n		<!-- [/End Search Form] -->\r\n`+]\r\n[+as.showIntro:is=`1`:then=`\r\n<p class=\"ajaxSearch_intro\" id=\"ajaxSearch_intro\">[+as.introMessage+]</p>\r\n`+]',0),(7,'slideshow','Slideshow template',0,8,0,'<!-- [Slideshow] -->\r\n<div class=\"row\" id=\"slideshow\">\r\n	<div class=\"small-12 columns\">\r\n		<ul>\r\n			<li>\r\n				<img src=\"[*slide-img1*]\" alt=\"#\">\r\n				<div class=\"slideshow-caption\">[*slide-text1*]</div>\r\n			</li>\r\n			<li>\r\n				<img src=\"[*slide-img2*]\" alt=\"#\">\r\n				<div class=\"slideshow-caption\">[*slide-text2*]</div>\r\n			</li>\r\n			<li>\r\n				<img src=\"[*slide-img3*]\" alt=\"#\">\r\n				<div class=\"slideshow-caption\">[*slide-text3*]</div>\r\n			</li>\r\n			<li>\r\n				<img src=\"[*slide-img4*]\" alt=\"#\">\r\n				<div class=\"slideshow-caption\">[*slide-text4*]</div>\r\n			</li>		\r\n		</ul>\r\n	</div>\r\n</div>\r\n<!-- [/End Slideshow] -->',0),(8,'default-list','Show a list of second-level content',0,8,0,'<!-- [Default List] -->\r\n<div class=\"default-list\">\r\n	<h2><a href=\"[+url+]\">[+longtitle+]</a></h2>\r\n	<p>[+introtext+]</p>\r\n</div>\r\n',0),(9,'sidebar','Sidebar template',0,8,0,'	<!-- [Sidebar] -->\r\n	<aside class=\"large-4 columns\" id=\"sidebar\">\r\n\r\n		[[Wayfinder? \r\n			&startId=`[[UltimateParent? &topLevel=`1`]]` \r\n			&displayStart=`0`\r\n			&level=`1` 			\r\n			&sortBy=`menuindex`\r\n			&sortOrder=`ASC`\r\n			&outerTpl=`wayfinder-sidebar-outerTpl`\r\n		]]\r\n	\r\n		<div class=\"sidebar-box\">\r\n			<h3>[*sidebar-title1@1*]</h3>\r\n			[*sidebar-text1@1*]\r\n		</div>\r\n	\r\n		<div class=\"sidebar-box\">\r\n			<h3>[*sidebar-title2@1*]</h3>\r\n			[*sidebar-text2@1*]\r\n		</div>\r\n	\r\n		<div class=\"sidebar-box\">\r\n			<h3>[*sidebar-title3@1*]</h3>\r\n			[*sidebar-text3@1*]\r\n		</div>\r\n		<div class=\"sidebar-box\">\r\n			<h3>[*sidebar-title4@1*]</h3>\r\n			[*sidebar-text4@1*]\r\n		</div>		\r\n	</aside>\r\n	<!-- [/End Sidebar] -->	',0),(10,'form-template','Form template',0,6,0,'<!-- [Form] -->	\r\n[+validationmessage+]\r\n<form method=\"post\" action=\"[~[*id*]~]\" name=\"contactform\" id=\"contactform\">\r\n	<fieldset>\r\n		<legend>Contact Form</legend>\r\n				\r\n		<div class=\"contactform\">\r\n			<label>Name</label>					\r\n			<input type=\"text\" maxlength=\"60\" class=\"required-name\" placeholder=\"Name*\" name=\"name\" eform=\"Name:string:1\" />			\r\n		</div>\r\n\r\n		<div class=\"contactform\">				\r\n			<label>Email</label>	\r\n			<input type=\"text\" maxlength=\"60\" class=\"required-email\" placeholder=\"Email*\" name=\"email\" eform=\"Email:email:1\" />						\r\n		</div>\r\n\r\n		<div class=\"contactform\">				\r\n			<label>Subject</label>	\r\n			<input type=\"text\" maxlength=\"60\" class=\"required-subject\" placeholder=\"Subject*\" name=\"subjected\" eform=\"Subject:string:1\" />					\r\n		</div>\r\n\r\n		<div class=\"contactform-textarea\">				\r\n			<label>Text</label>	\r\n			<textarea class=\"required-text\" placeholder=\"Message*\" name=\"message\" eform=\"Message:string:1\"></textarea>\r\n		</div>	\r\n			\r\n		<input type=\"submit\" class=\"button small\" name=\"submit\" value=\"Send\" />\r\n			\r\n	</fieldset>\r\n</form>				\r\n<!-- [/End Form] -->',0),(11,'wayfinder-sidebar-outerTpl','Wayfinder outer template',0,8,0,'		<div class=\"sidebar-box\">\r\n			<h3>[*menutitle@ultimateparent*]</h3>\r\n			<ul>\r\n				[+wf.wrapper+]\r\n			</ul>\r\n		</div>',0),(12,'form-report','Form report template',0,6,0,'<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\"><tr><td align=\"center\" valign=\"top\" style=\"background: #FFF; padding: 20px 0 0;\">\r\n\r\n<table width=\"100%\" height=\"236\" border=\"0\" style=\"border: 1px solid #DDD; font-family: Arial; font-size: 14px; max-width: 650px; border-collapse:collapse;\" >\r\n	<tr valign=\"top\">\r\n	  <td colspan=\"3\" valign=\"middle\" bgcolor=\"#333\">\r\n		<p style=\"color: #FFF; padding: 0 10px 0;\">This is an email from <strong style=\"color:white;\">[+name+]</strong>.  The details are as follows:</p>\r\n	  </td>\r\n	</tr>\r\n	<tr valign=\"top\">\r\n	  <td height=\"43\" width=\"23\" valign=\"middle\" bgcolor=\"#F0F0F0\">&nbsp;</td>\r\n	  <td height=\"43\" width=\"122\" valign=\"middle\" bgcolor=\"#F0F0F0\">Name:</td>\r\n	  <td width=\"1053\" valign=\"middle\" bgcolor=\"#F0F0F0\">[+name+]</td>\r\n	</tr>\r\n	<tr valign=\"top\">\r\n	  <td height=\"43\" valign=\"middle\">&nbsp;</td>\r\n	  <td height=\"43\" valign=\"middle\">Email:</td>\r\n	  <td height=\"43\" valign=\"middle\">[+email+]</td>\r\n	</tr>\r\n	<tr valign=\"top\">\r\n	  <td height=\"43\" valign=\"middle\" bgcolor=\"#F0F0F0\">&nbsp;</td>\r\n	  <td height=\"43\" valign=\"middle\" bgcolor=\"#F0F0F0\">Subject:</td>\r\n	  <td height=\"43\" valign=\"middle\" bgcolor=\"#F0F0F0\">[+subjected+]</td>\r\n	</tr>\r\n	<tr valign=\"top\">\r\n	  <td height=\"43\" valign=\"middle\">&nbsp;</td>\r\n	  <td height=\"43\" valign=\"middle\">Message:</td>\r\n	  <td height=\"43\" valign=\"middle\" >[+message+]</td>\r\n	</tr>\r\n</table>\r\n\r\n<table width=\"100%\" border=\"0\" style=\"font-family: Arial; font-size: 14px; max-width: 650px; border-collapse:collapse;\" >\r\n	<tr valign=\"top\">\r\n	  <td height=\"43\" valign=\"middle\">\r\n	    <p style=\"text-align: left;\">Reply here: <a href=\"mailto:[+email+]?subject=RE:[+subjected+]\">[+email+]</a></p>\r\n	  </td>\r\n	</tr>\r\n</table>\r\n\r\n</td></tr></table>',0),(13,'attribution-cookipedia','Creative Commons attribution',0,1,0,'<p id=\"cc-licence\"><a href=\"http://creativecommons.org/licenses/by-sa/3.0/\"><img src=\"assets/images/recipes/cc-by-sa.png\" alt=\"Creative Commons\" /></a> Based on material from <a href=\"http://www.cookipedia.co.uk\">Cookipedia</a></p>\r\n',0),(14,'recipe-ListTpl','Index listing template for recipes',0,1,0,'<article class=\"row\">\r\n    <div class=\"small-7 large-8 columns recipe-right\">\r\n        <h3><a href=\"[+url+]\">[+longtitle+]</a></h3>\r\n        <p>[+introtext+]</p>\r\n    </div>\r\n    <div class=\"small-5 large-4 columns recipe-left\">\r\n        <a href=\"[+url+]\">[+food-shot+]</a>\r\n    </div>\r\n</article>\r\n',0),(15,'help-page-ListTpl','Index listing template for Help page articles',0,1,0,'<article class=\"row\">\r\n    <div class=\"small-12 columns\">\r\n        <h3><a href=\"[+url+]\">[+longtitle+]</a></h3>\r\n        [+summary+] <div><a href=\"[+url+]\" class=\"button\">Read More</a></div>\r\n    </div>\r\n</article>\r\n',0);
/*!40000 ALTER TABLE `clipper_site_htmlsnippets` ENABLE KEYS */;
UNLOCK TABLES;

