--
-- Table structure for table `clipper_site_modules`
--

DROP TABLE IF EXISTS `clipper_site_modules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `clipper_site_modules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '',
  `description` varchar(255) NOT NULL DEFAULT '0',
  `editor_type` int(11) NOT NULL DEFAULT 0 COMMENT '0-plain text,1-rich text,2-code editor',
  `disabled` tinyint(4) NOT NULL DEFAULT 0,
  `category` int(11) NOT NULL DEFAULT 0 COMMENT 'category id',
  `wrap` tinyint(4) NOT NULL DEFAULT 0,
  `locked` tinyint(4) NOT NULL DEFAULT 0,
  `icon` varchar(255) NOT NULL DEFAULT '' COMMENT 'url to module icon',
  `enable_resource` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'enables the resource file feature',
  `resourcefile` varchar(255) NOT NULL DEFAULT '' COMMENT 'a physical link to a resource file',
  `createdon` int(11) NOT NULL DEFAULT 0,
  `editedon` int(11) NOT NULL DEFAULT 0,
  `guid` varchar(32) NOT NULL DEFAULT '' COMMENT 'globally unique identifier',
  `enable_sharedparams` tinyint(4) NOT NULL DEFAULT 0,
  `properties` text DEFAULT NULL,
  `modulecode` mediumtext DEFAULT NULL COMMENT 'module boot up code',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8 COLLATE=utf8_general_ci COMMENT='Site Modules';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `clipper_site_modules`
--

LOCK TABLES `clipper_site_modules` WRITE;
/*!40000 ALTER TABLE `clipper_site_modules` DISABLE KEYS */;
INSERT INTO `clipper_site_modules` VALUES (1,'Res Manager','<strong>1.1</strong> Quickly perform bulk updates to the Documents in your site including templates, publishing details, and permissions',0,0,2,0,0,'',0,'',0,0,'',1,'','include_once(MODX_BASE_PATH.\'assets/modules/resmanager/classes/resmanager.class.php\');\ninclude_once(MODX_BASE_PATH.\'assets/modules/resmanager/classes/rm_frontend.class.php\');\ninclude_once(MODX_BASE_PATH.\'assets/modules/resmanager/classes/rm_backend.class.php\');\n\n$rm = new ResManager($modx);\n$rmf = new ResManagerFrontend($rm, $modx);\n$rmb = new ResManagerBackend($rm, $modx);\n\n$rm->ph = $rm->getLang();\n$rm->ph[\'theme\'] = $rm->getTheme();\n$rm->ph[\'ajax.endpoint\'] = MODX_SITE_URL.\'assets/modules/resmanager/tv.ajax.php\';\n$rm->ph[\'datepicker.year_range\'] = $modx->config[\'datepicker_year_range\'];\n$rm->ph[\'date.format\'] = $modx->config[\'date_format\'];\n$rm->ph[\'time.format\'] = $modx->config[\'time_format\'];\n\n$rm->ph[\'style.css\'] = \'\';\nif (is_file(MODX_MANAGER_PATH.\"media/style/$manager_theme/style.css\")) {\n    $rm->ph[\'style.css\'] = \'<link rel=\"stylesheet\" href=\"media/style/\'.$manager_theme.\"/style.css\\\" />\\n\";\n}\n\n$rm->ph[\'manager.css\'] = \'\';\nif (is_file(MODX_MANAGER_PATH.\"media/style/$manager_theme/manager.css\")) {\n    $rm->ph[\'manager.css\'] =  \'<link rel=\"stylesheet\" href=\"media/style/\'.$manager_theme.\"/manager.css\\\" />\\n\";\n}\n\n$rm->ph[\'jquery\'] = $modx->getJqueryTag();\n$rm->ph[\'jquery.ui\'] = $modx->getJqueryPluginTag(\'jquery-ui-custom-clippermanager\', \'jquery-ui-custom-clippermanager.min.js\');\n$rm->ph[\'jquery.timepicker\'] =$modx->getJqueryPluginTag(\'jquery-ui-timepicker\', \'jquery-ui-timepicker-addon.js\');\n\nif (isset($_POST[\'tabAction\'])) {\n\n    $rmb->handlePostback();\n} else {\n\n    $rmf->getViews();\n    echo $rm->parseTemplate(\'main.tpl\', $rm->ph);\n}\n');
/*!40000 ALTER TABLE `clipper_site_modules` ENABLE KEYS */;
UNLOCK TABLES;

