INSERT INTO `clipper_site_plugins` VALUES (1,'ManagerManager','<strong>clipper-0.3.13</strong> Customize the MODx Manager to offer bespoke admin functions for end users.',0,2,0,'// You can put your ManagerManager rules EITHER in a chunk OR in an external file - whichever suits your development style the best\n\n// To use an external file, put your rules in /assets/plugins/managermanager/mm_rules.inc.php \n// (you can rename default.mm_rules.inc.php and use it as an example)\n// The chunk SHOULD have php opening tags at the beginning and end\n\n// If you want to put your rules in a chunk (so you can edit them through the Manager),\n// create the chunk, and enter its name in the configuration tab.\n// The chunk should NOT have php tags at the beginning or end\n\n// You don\'t need to change anything else from here onwards\n//-------------------------------------------------------\n\n// Run the main code\n$asset_path = $modx->config[\'base_path\'] . \'assets/plugins/managermanager/mm.inc.php\';\ninclude($asset_path);\n',0,'&config_chunk=Configuration Chunk;text;mm_rules; &which_jquery=jQuery source;list;local (assets/js),remote (google code),manual url (specify below);local (assets/js) &js_src_type=jQuery URL override;text;',0,''),(2,'Search Highlight','<strong>clipper-1.5.1</strong> Used with AjaxSearch to show search terms highlighted on page linked from search results',0,3,0,'/*\n  ------------------------------------------------------------------------\n  Plugin: Search_Highlight clipper-v1.5.1\n  ------------------------------------------------------------------------\n  Changes:\n  18/03/10 - Remove possibility of XSS attempts being passed in the URL\n           - look-behind assertion improved\n  29/03/09 - Removed urldecode calls;\n           - Added check for magic quotes - if set, remove slashes\n           - Highlights terms searched for when target is a HTML entity\n  18/07/08 - advSearch parameter and pcre modifier added\n  10/02/08 - Strip_tags added to avoid sql injection and XSS. Use of $_REQUEST\n  01/03/07 - Added fies/updates from forum from users mikkelwe/identity\n  (better highlight replacement, additional div around term/removal message)\n  ------------------------------------------------------------------------\n  Description: When a user clicks on the link from the AjaxSearch results\n    the target page will have the terms highlighted.\n  ------------------------------------------------------------------------\n  Created By:  Susan Ottwell (sottwell@sottwell.com)\n               Kyle Jaebker (kjaebker@muddydogpaws.com)\n\n  Refactored by Coroico (www.modx.wangba.fr) and TS\n  ------------------------------------------------------------------------\n  Based off the the code by Susan Ottwell (www.sottwell.com)\n    http://modxcms.com/forums/index.php/topic,1237.0.html\n  ------------------------------------------------------------------------\n  CSS:\n    The classes used for the highlighting are the same as the AjaxSearch\n  ------------------------------------------------------------------------\n  Notes:\n    To add a link to remove the highlighting and to show the searchterms\n    put the following on your page where you would like this to appear:\n\n      <!--search_terms-->\n\n    Example output for this:\n\n      Search Terms: the, template\n      Remove Highlighting\n\n    Set the following variables to change the text:\n\n      $termText - the text before the search terms\n      $removeText - the text for the remove link\n  ------------------------------------------------------------------------\n*/\nglobal $database_connection_charset;\n// Conversion code name between html page character encoding and Mysql character encoding\n// Some others conversions should be added if needed. Otherwise Page charset = Database charset\n$pageCharset = array(\n  \'utf8\' => \'UTF-8\',\n  \'latin1\' => \'ISO-8859-1\',\n  \'latin2\' => \'ISO-8859-2\'\n);\n\nif (isset($_REQUEST[\'searched\']) && isset($_REQUEST[\'highlight\'])) {\n\n  // Set these to customize the text for the highlighting key\n  // --------------------------------------------------------\n     $termText = \'<div class=\"searchTerms\">Search Terms: \';\n     $removeText = \'Remove Highlighting\';\n  // --------------------------------------------------------\n\n  $highlightText = $termText;\n  $advsearch = \'oneword\';\n\n  $dbCharset = $database_connection_charset;\n  $pgCharset = array_key_exists($dbCharset,$pageCharset) ? $pageCharset[$dbCharset] : $dbCharset;\n\n  // magic quotes check\n  if (get_magic_quotes_gpc()){\n    $searched = $modx->stripTags(stripslashes($_REQUEST[\'searched\']));\n    $highlight = $modx->stripTags(stripslashes($_REQUEST[\'highlight\']));\n    if (isset($_REQUEST[\'advsearch\'])) $advsearch = $modx->stripTags(stripslashes($_REQUEST[\'advsearch\']));\n  }\n  else {\n    $searched = $modx->stripTags($_REQUEST[\'searched\']);\n    $highlight = $modx->stripTags($_REQUEST[\'highlight\']);\n    if (isset($_REQUEST[\'advsearch\'])) $advsearch = $modx->stripTags($_REQUEST[\'advsearch\']);\n  }\n\n  if ($advsearch != \'nowords\') {\n\n    $searchArray = array();\n    if ($advsearch == \'exactphrase\') $searchArray[0] = $searched;\n    else $searchArray = explode(\' \', $searched);\n\n    $searchArray = array_unique($searchArray);\n    $nbterms = count($searchArray);\n    $searchTerms = array();\n    for($i=0;$i<$nbterms;$i++){\n      // Consider all possible combinations\n      $word_ents = array();\n      $word_ents[] = $searchArray[$i];\n      $word_ents[] = htmlentities($searchArray[$i], ENT_NOQUOTES, $pgCharset);\n      $word_ents[] = htmlentities($searchArray[$i], ENT_COMPAT, $pgCharset);\n      $word_ents[] = htmlentities($searchArray[$i], ENT_QUOTES, $pgCharset);\n      // Avoid duplication\n      $word_ents = array_unique($word_ents);\n      foreach($word_ents as $word) $searchTerms[]= array(\'term\' => $word, \'class\' => $i+1);\n    }\n\n    $output = $modx->documentOutput; // get the parsed document\n    $body = explode(\"<body\", $output); // break out the head\n\n    $highlightClass = explode(\' \',$highlight); // break out the highlight classes\n    /* remove possibility of XSS attempts being passed in URL */\n    foreach ($highlightClass as $key => $value) {\n       $highlightClass[$key] = preg_match(\'/[^A-Za-z0-9_-]/ms\', $value) == 1 ? \'\' : $value;\n    }\n\n    $pcreModifier = ($pgCharset == \'UTF-8\') ? \'iu\' : \'i\';\n    $lookBehind = \'/(?<!&|&[\\w#]|&[\\w#]\\w|&[\\w#]\\w\\w|&[\\w#]\\w\\w\\w|&[\\w#]\\w\\w\\w\\w|&[\\w#]\\w\\w\\w\\w\\w)\';  // avoid a match with a html entity\n    $lookAhead = \'(?=[^>]*<)/\'; // avoid a match with a html tag\n\n    $nbterms = count($searchTerms);\n    for($i=0;$i<$nbterms;$i++){\n      $word = $searchTerms[$i][\'term\'];\n      $class = $highlightClass[0].\' \'.$highlightClass[$searchTerms[$i][\'class\']];\n\n      $highlightText .= ($i > 0) ? \', \' : \'\';\n      $highlightText .= \'<span class=\"\'.$class.\'\">\'.$word.\'</span>\';\n\n      $pattern = $lookBehind . preg_quote($word, \'/\') . $lookAhead . $pcreModifier;\n      $replacement = \'<span class=\"\' . $class . \'\">${0}</span>\';\n      $body[1] = preg_replace($pattern, $replacement, $body[1]);\n    }\n\n    $output = implode(\"<body\", $body);\n\n    $removeUrl = $modx->makeUrl($modx->documentIdentifier);\n    $highlightText .= \'<br /><a href=\"\'.$removeUrl.\'\" class=\"ajaxSearch_removeHighlight\">\'.$removeText.\'</a></div>\';\n\n    $output = str_replace(\'<!--search_terms-->\',$highlightText,$output);\n    $modx->documentOutput = $output;\n  }\n}\n',0,'',0,''),(3,'Quick Manager+','<strong>clipper-1.6</strong> Enables QuickManager+ front end content editing support',0,2,0,'// In manager\nif (isset($_SESSION[\'mgrValidated\'])) {\n\n    $show = TRUE;\n\n    if ($disabled  != \'\') {\n        $arr = explode(\",\", $disabled );\n        if (in_array($modx->documentIdentifier, $arr)) {\n            $show = FALSE;\n        }\n    }\n\n    if ($show) {\n        // Replace [*#tv*] with QM+ edit TV button placeholders\n        if ($tvbuttons == \'true\') {\n            $e = $modx->Event;\n            if ($e->name == \'OnParseDocument\') {\n                 $output = &$modx->documentOutput;\n                 $output = preg_replace(\'~\\[\\*#(.*?)\\*\\]~\', \'<!-- \'.$tvbclass.\' $1 -->[*$1*]\', $output);\n                 $modx->documentOutput = $output;\n             }\n         }\n        // In manager\n        if (isset($_SESSION[\'mgrValidated\'])) {\n            require_once($modx->config[\'base_path\'].\'assets/plugins/qm/qm.inc.php\');\n            $qm = new Qm($modx, $noconflict === \'true\', $loadtb, $tbwidth, $tbheight, $hidefields, $hidetabs, $hidesections, $addbutton, $custombutton, $managerbutton, $logout, $autohide, $editbuttons, $editbclass, $newbuttons, $newbclass, $tvbuttons, $tvbclass);\n        }\n    }\n}\n',0,'&noconflict=Use own instance of jquery;list;true,false;true &loadtb=Load modal box in front-end;list;true,false;true &tbwidth=Modal box window width;text;80% &tbheight=Modal box window height;text;90% &hidefields=Hide document fields from front-end editors;text;parent &hidetabs=Hide document tabs from front-end editors;text; &hidesections=Hide document sections from front-end editors;text; &addbutton=Show add document here button;list;true,false;true &custombutton=Custom buttons;textarea; &managerbutton=Show go to manager button;list;true,false;true &logout=Logout to;list;manager,front-end;manager &disabled=Plugin disabled on documents;text; &autohide=Autohide toolbar;list;true,false;true &editbuttons=Inline edit buttons;list;true,false;false &editbclass=Edit button CSS class;text;qm-edit &newbuttons=Inline new resource buttons;list;true,false;false &newbclass=New resource button CSS class;text;qm-new &tvbuttons=Inline template variable buttons;list;true,false;false &tvbclass=Template variable button CSS class;text;qm-tv',0,''),(4,'TinyMCE Rich Text Editor','<strong>clipper-3.5.3</strong> Javascript WYSIWYG Editor',0,2,0,'// Set the name of the plugin folder\n$plugin_dir = \"tinymce\";\n\n// Set path and base setting variables\nif(!isset($mce_path))\n{ \n	$mce_path = MODX_BASE_PATH . \'assets/plugins/\'.$plugin_dir . \'/\'; \n	$mce_url  = MODX_BASE_URL  . \'assets/plugins/\'.$plugin_dir . \'/\'; \n}\n\n$params[\'customparams\']    = $customparams;\n$params[\'blockFormats\']    = $mce_formats;\n$params[\'entity_encoding\'] = $entity_encoding;\n$params[\'entities\']        = $entities;\n$params[\'pathoptions\']     = $mce_path_options;\n$params[\'resizing\']        = $mce_resizing;\n$params[\'disabledButtons\'] = $disabledButtons;\n$params[\'link_list\']       = $link_list;\n$params[\'theme\']           = $webtheme;\n$params[\'custom_plugins\']  = $webPlugins;\n$params[\'custom_buttons1\'] = $webButtons1;\n$params[\'custom_buttons2\'] = $webButtons2;\n$params[\'custom_buttons3\'] = $webButtons3;\n$params[\'custom_buttons4\'] = $webButtons4;\n$params[\'toolbar_align\']   = $webAlign;\n$params[\'width\']           = $width;\n$params[\'height\']          = $height;\n\n$params[\'mce_path\']        = $mce_path;\n$params[\'mce_url\']         = $mce_url;\n\ninclude_once $mce_path . \'lang/tinymce.lang.php\';\ninclude_once $mce_path . \'tinymce.functions.php\';\n\n$mce = new TinyMCE($params);\n\n// Handle event\n$e = &$modx->Event; \nswitch ($e->name)\n{\n	case \"OnRichTextEditorRegister\": // register only for backend\n		$e->output(\"TinyMCE\");\n		break;\n\n	case \"OnRichTextEditorInit\": \n		if($editor!==\"TinyMCE\") return;\n		\n		$params[\'elements\']        = $elements;\n		$params[\'css_selectors\']   = $modx->config[\'tinymce_css_selectors\'];\n		$params[\'use_browser\']     = $modx->config[\'use_browser\'];\n		$params[\'editor_css_path\'] = $modx->config[\'editor_css_path\'];\n		\n		if($modx->isBackend() || (intval($_GET[\'quickmanagertv\']) == 1 && isset($_SESSION[\'mgrValidated\'])))\n		{\n			$params[\'theme\']           = $modx->config[\'tinymce_editor_theme\'];\n			$params[\'language\']        = getTinyMCELang($modx->config[\'manager_language\']);\n			$params[\'frontend\']        = false;\n			$params[\'custom_plugins\']  = $modx->config[\'tinymce_custom_plugins\'];\n			$params[\'custom_buttons1\'] = $modx->config[\'tinymce_custom_buttons1\'];\n			$params[\'custom_buttons2\'] = $modx->config[\'tinymce_custom_buttons2\'];\n			$params[\'custom_buttons3\'] = $modx->config[\'tinymce_custom_buttons3\'];\n			$params[\'custom_buttons4\'] = $modx->config[\'tinymce_custom_buttons4\'];\n			$params[\'toolbar_align\']   = $modx->config[\'manager_direction\'];\n			$params[\'webuser\']         = null;\n			\n			$html = $mce->get_mce_script($params);\n		}\n		else\n		{\n			$frontend_language = isset($modx->config[\'fe_editor_lang\']) ? $modx->config[\'fe_editor_lang\']:\'\';\n			$webuser = (isset($modx->config[\'rb_webuser\']) ? $modx->config[\'rb_webuser\'] : null);\n			\n			$params[\'webuser\']         = $webuser;\n			$params[\'language\']        = getTinyMCELang($frontend_language);\n			$params[\'frontend\']        = true;\n			\n			$html = $mce->get_mce_script($params);\n		}\n		$e->output($html);\n		break;\n\n	case \"OnInterfaceSettingsRender\":\n		global $usersettings,$settings;\n		$action = $modx->manager->action;\n		switch ($action)\n		{\n			case 11:\n				$mce_settings = \'\';\n				break;\n			case 12:\n				$mce_settings = $usersettings;\n				break;\n			case 17:\n				$mce_settings = $settings;\n				break;\n			default:\n				$mce_settings = $settings;\n				break;\n		}\n		\n		$params[\'use_editor\']       = $modx->config[\'base_url\'].$modx->config[\'use_editor\'];\n        $params[\'editor_css_path\']  = $modx->config[\'editor_css_path\'];\n		$params[\'theme\']            = $mce_settings[\'tinymce_editor_theme\'];\n		$params[\'css_selectors\']    = $mce_settings[\'tinymce_css_selectors\'];\n		$params[\'custom_plugins\']   = $mce_settings[\'tinymce_custom_plugins\'];\n		$params[\'custom_buttons1\']  = $mce_settings[\'tinymce_custom_buttons1\'];\n		$params[\'custom_buttons2\']  = $mce_settings[\'tinymce_custom_buttons2\'];\n		$params[\'custom_buttons3\']  = $mce_settings[\'tinymce_custom_buttons3\'];\n		$params[\'custom_buttons4\']  = $mce_settings[\'tinymce_custom_buttons4\'];\n		\n		$html = $mce->get_mce_settings($params);\n		$e->output($html);\n		break;\n		\n	default :\n		return; // stop here - this is very important. \n		break; \n}\n',0,'&customparams=Custom Parameters;textarea; &mce_formats=Block Formats;text;p,h1,h2,h3,h4,h5,h6,div,blockquote,code,pre &entity_encoding=Entity Encoding;list;named,numeric,raw;named &entities=Entities;text; &mce_path_options=Path Options;list;rootrelative,docrelative,fullpathurl;docrelative &mce_resizing=Advanced Resizing;list;true,false;true &disabledButtons=Disabled Buttons;text; &link_list=Link List;list;enabled,disabled;enabled &webtheme=Web Theme;list;simple,editor,creative,custom;simple &webPlugins=Web Plugins;text;style,advimage,advlink,searchreplace,contextmenu,paste,fullscreen,nonbreaking,xhtmlxtras,visualchars,media &webButtons1=Web Buttons 1;text;undo,redo,selectall,|,pastetext,pasteword,|,search,replace,|,nonbreaking,hr,charmap,|,image,link,unlink,anchor,media,|,cleanup,removeformat,|,fullscreen,code,help &webButtons2=Web Buttons 2;text;bold,italic,underline,strikethrough,sub,sup,|,|,blockquote,bullist,numlist,outdent,indent,|,justifyleft,justifycenter,justifyright,justifyfull,|,styleselect,formatselect,|,styleprops &webButtons3=Web Buttons 3;text; &webButtons4=Web Buttons 4;text; &webAlign=Web Toolbar Alignment;list;ltr,rtl;ltr &width=Width;text;100% &height=Height;text;400',0,''),(5,'TransAlias','<strong>clipper-1.1.1</strong> Human readible URL translation supporting multiple languages and overrides.',0,2,0,'require MODX_BASE_PATH.\'assets/plugins/transalias/plugin.transalias.php\';\n',0,'&table_name=Trans table;list;common,russian,dutch,german,czech,utf8,utf8lowercase;utf8lowercase &char_restrict=Restrict alias to;list;lowercase alphanumeric,alphanumeric,legal characters;legal characters &remove_periods=Remove Periods;list;Yes,No;No &word_separator=Word Separator;list;dash,underscore,none;dash &override_tv=Override TV name;string;',0,''),(7,'Brackify','Remove extra space between tag brackets (inserted to prevent parsing)',0,3,0,'// <?php // Note PHP tag in comment to help editing; plugins don\'t have an active PHP tag.\r\n\r\n// Brackify\r\n// Plugin to remove extra space added between tag brackets\r\n// (there to prevent tags being parsed)\r\n// Use with OnWebPagePrerender system event checked\r\n\r\n$e = &$modx->Event;\r\nif ($e->name == \"OnWebPagePrerender\"){\r\n    $page = $modx->documentOutput;\r\n    $brackets = \'[ (,) ],{ {,} },[ [,] ],[ !,! ],[ +,+ ],[ *,* ],[ ^,^ ],[ ~,~ ]\' ;\r\n    $despaced = str_replace(\' \',\'\',$brackets);\r\n    $search = explode(\',\',$brackets);\r\n    $replace = explode (\',\',$despaced);\r\n    $page = str_replace($search,$replace,$page);\r\n    $modx->documentOutput = $page;\r\n}\r\n',0,'',0,' ');
