INSERT INTO `clipper_site_templates` VALUES (3,'Minimal Template','Default minimal empty template (content returned only)',0,0,'',0,'[*content*]',0,0,'',0),(4,'Home Page','Home Page template',0,8,'',0,'{{head}}\r\n<body>\r\n\r\n{{header}}\r\n[[ShowSlides? &switch=`[*show-slideshow*]` &chunk=`slideshow`]]\r\n\r\n<!-- [Content] -->\r\n<div class=\"row\" id=\"content\">\r\n\r\n	<!-- [Text] -->\r\n	<div class=\"large-8 columns\" id=\"text\">\r\n		<h1>[*longtitle*]</h1>\r\n		[*content*]\r\n                [*plain-text-section*]\r\n	</div>\r\n	<!-- [/End Text] -->	\r\n\r\n	{{sidebar}}\r\n	\r\n</div>\r\n<!-- [/End Content] -->\r\n\r\n{{footer}}\r\n\r\n</body>\r\n</html>',0,0,'0',0),(5,'Basic Template','Default template',0,8,'',0,'{{head}}\r\n<body>\r\n\r\n{{header}}\r\n\r\n<!-- [Content] -->\r\n<div class=\"row\" id=\"content\">\r\n\r\n	<!-- [Text] -->\r\n	<div class=\"large-8 columns\" id=\"text\">\r\n		<h1>[*longtitle*]</h1>\r\n		[*content*]\r\n                [*plain-text-section*]\r\n	</div>\r\n	<!-- [/End Text] -->	\r\n\r\n	{{sidebar}}\r\n	\r\n</div>\r\n<!-- [/End Content] -->\r\n\r\n{{footer}}\r\n\r\n</body>\r\n</html>',0,0,'0',0),(6,'Recipe Template','Recipe template',0,8,'',0,'{{head}}\r\n<body>\r\n\r\n{{header}}\r\n\r\n<!-- [Content] -->\r\n<div class=\"row\" id=\"content\">\r\n\r\n	<!-- [Text] -->\r\n	<div class=\"large-8 columns\" id=\"text\">\r\n		<h1>[*longtitle*]</h1>\r\n		[*content*]\r\n                [*plain-text-section*] \r\n	</div>\r\n	<!-- [/End Text] -->	\r\n\r\n	{{sidebar}}\r\n	\r\n</div>\r\n<!-- [/End Content] -->\r\n\r\n{{footer}}\r\n\r\n</body>\r\n</html>',0,0,'0',0);
