INSERT INTO `clipper_site_tmplvar_contentvalues` VALUES (2,2,1,'assets/images/slide/2.jpg'),(3,3,1,'assets/images/slide/3.jpg'),(4,4,1,'assets/images/slide/4.jpg'),(5,5,1,'<p>Photo1, by <a href=\"http://www.freerangestock.com\" target=\"_blank\">Freerangestock.com</a></p>'),(6,6,1,'<p>Photo2, by <a href=\"http://www.freerangestock.com\" target=\"_blank\">Freerangestock.com</a></p>'),(7,7,1,'<p>Photo3, by <a href=\"http://www.freerangestock.com\" target=\"_blank\">Freerangestock.com</a></p>'),(8,8,1,'<p>Photo4, by <a href=\"http://www.freerangestock.com\" target=\"_blank\">Freerangestock.com</a></p>'),(9,9,1,'1'),(10,1,1,'assets/images/slide/1.jpg'),(11,10,1,'External Links'),(12,11,1,'Manager login'),(13,12,1,'About ClipperCMS'),(14,13,1,'Feedback'),(15,14,1,'<ul>\r\n<li><a href=\"http://www.clippercms.com/download/current-release.html\" target=\"_blank\">Download Clipper</a></li>\r\n<li><a href=\"http://www.clippercms.com/forum/\" target=\"_blank\">Community Forums</a></li>\r\n<li><a href=\"http://www.clippercms.com/documentation\" target=\"_blank\">Documentation</a></li>\r\n</ul>'),(16,15,1,'<p><a href=\"[(site_url)]manager/\" target=\"_blank\">Click here</a> to login to your <strong>[(site_name)]</strong> administration panel.</p>'),(17,16,1,'<p>Clipper is a flexible and powerful open source content management system released under the GPL license, you can use this web software to build websites, personal blogs and also complex and dynamic applications.</p>'),(18,17,1,'<p>We would really appreciate your feedback regarding Clipper, as this would help us improve the system. Feel free to contact us <a href=\"mailto:hello@clippercms.org?subject=ClipperCMS%20Feedback%20(demo%20website)\">by email</a> or let us know your impressions and suggestions directly on <a href=\"http://www.clippercms.com/forum/\" target=\"_blank\">Clipper forum</a>.</p>'),(19,18,11,'assets/images/recipes/300px-Lamb_hot_pot_recipe.jpg'),(20,18,12,'assets/images/recipes/300px-Baked_aubergines_with_tomatoes_and_Parmesan_recipe.jpg'),(21,18,13,'assets/images/recipes/300px-Borscht_recipe.jpg'),(22,19,5,'<div id=\"help-pages\">\r\n[[List? \r\n    &tpl=`help-page-ListTpl` \r\n    &orderBy=`menuindex ASC`\r\n    &extenders=`summary` \r\n]]\r\n</div>'),(23,19,3,'<div id=\"recipes\">\r\n[[List? \r\n    &display=`4` \r\n    &depth=`0` \r\n    &tpl=`recipe-ListTpl` \r\n    &orderBy=`menuindex ASC` \r\n    &showInMenuOnly=`1` \r\n    &noResults=` `\r\n]]\r\n</div>'),(24,19,6,'[!eForm? \r\n	&formid=`contactform` \r\n	&tpl=`form-template` \r\n	&report=`form-report` \r\n	&language=`english` \r\n	&from=`((email))` \r\n	&to=`[(emailsender)]`\r\n	&subject=`Contact Form | [(site_name)]` \r\n	&gotoid=`10`  \r\n!]');
/*!40000 ALTER TABLE `clipper_site_tmplvar_contentvalues` ENABLE KEYS */;
